package net.evarius.terranexus.landlord;
import com.mojang.serialization.Codec;import com.mojang.serialization.codecs.RecordCodecBuilder;import net.evarius.terranexus.config.ConfigManager;import net.minecraft.datafixer.DataFixTypes;import net.minecraft.server.MinecraftServer;import net.minecraft.world.PersistentState;import net.minecraft.world.PersistentStateType;import java.util.ArrayList;import java.util.List;import java.util.UUID;
public final class AdministrationAuditState extends PersistentState{private static final Codec<AdministrationAuditState> CODEC=RecordCodecBuilder.create(i->i.group(AdministrationAuditEntry.CODEC.listOf().optionalFieldOf("entries",List.of()).forGetter(s->s.entries)).apply(i,AdministrationAuditState::new));private static final PersistentStateType<AdministrationAuditState> TYPE=new PersistentStateType<>("terranexus_administration_audit",AdministrationAuditState::new,CODEC,DataFixTypes.LEVEL);private final List<AdministrationAuditEntry> entries;public AdministrationAuditState(){this(new ArrayList<>());}private AdministrationAuditState(List<AdministrationAuditEntry> entries){this.entries=new ArrayList<>(entries);}public static AdministrationAuditState get(MinecraftServer server){return server.getOverworld().getPersistentStateManager().getOrCreate(TYPE);}public void log(UUID actor,String action,String areaId,String details){entries.add(new AdministrationAuditEntry(System.currentTimeMillis(),actor.toString(),action,areaId,details));int max=ConfigManager.logging().maximumLandAuditEntries;if(entries.size()>max)entries.subList(0,entries.size()-max).clear();markDirty();}public List<AdministrationAuditEntry> allRecent(){List<AdministrationAuditEntry> copy=new ArrayList<>(entries);java.util.Collections.reverse(copy);return List.copyOf(copy);}}
